export const categoryRemuneration='<table><tr><td rowspan="2">役員区分</td><td rowspan="2">報酬等の総額(百万円)</td><td colspan="2">報酬等の種類別の総額(百万円)</td><td rowspan="2">対象となる役員の員数(人)</td></tr><tr><td>固定報酬</td><td>業績連動報酬</td></tr><tr><td>取締役（社外取締役を除く）</td><td>341</td><td>155</td><td>115</td><td>10</td></tr><tr><td>社外役員</td><td>30</td><td>30</td><td>－</td><td>3</td></tr><tr><td>合計</td><td>371</td><td>185</td><td>115</td><td>13</td></tr></table>';
