export const nestedCategoryRemuneration='<table><tr><td rowspan="2" colspan="2">役員区分</td><td rowspan="2">報酬等の総額(百万円)</td><td colspan="3">報酬等の種類別の総額(百万円)</td><td rowspan="2">対象となる役員の員数</td></tr><tr><td colspan="2">金銭報酬</td><td>長期インセンティブ型報酬</td></tr><tr><td></td><td></td><td></td><td>基本報酬</td><td>賞与</td><td>譲渡制限付株式</td><td>（人）</td></tr><tr><td colspan="2">取締役</td><td>341</td><td>155</td><td>115</td><td>70</td><td>10</td></tr><tr><td rowspan="2">社外役員</td><td>社外取締役</td><td>63</td><td>63</td><td>－</td><td>－</td><td>5</td></tr><tr><td>社外監査役</td><td>30</td><td>30</td><td>－</td><td>－</td><td>4</td></tr></table>';
export function remunerationDocument(options:{raw?:string;docID?:string;entity?:string;instant?:string;three?:boolean;namespace?:string}={}):RemunerationDocument{
 const raw=options.raw??'<p>当事業年度に係る報酬です。退任者を含みます。</p>'+(options.three?nestedCategoryRemuneration:categoryRemuneration)+'<p>個人別連結報酬</p>'+individualRemuneration;
 const d=majorDocument({...options,raw}),hash=createHash('sha256').update(raw).digest('hex');
 return {xml:d.xml.replaceAll('MajorShareholdersTextBlock','RemunerationForDirectorsAndOtherOfficersTextBlock'),selection:{...d.selection,kind:'officerRemuneration'},period:{startDate:'2025-04-01',endDate:'2026-03-31'},tables:[{tableIndex:0,rawSha256:hash,kind:'category',headerRows:options.three?3:2},{tableIndex:1,rawSha256:hash,kind:'individual',headerRows:2}]};
}
